/* @author MILO-GAO(高振銘)@2020 */ package page2020.view;import java.util.ArrayList;import java.util.Arrays;import java.util.LinkedHashMap;import java.util.LinkedHashSet;import java.util.List;import java.util.Map;import java.util.Set;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.util.StringUtils;import page2020.util.EmptyUtil;public class Tag<T> extends Content<T> {	public static final class Attr {		public static final String accessKey = "accesskey";		public static final String contentEditable = "contenteditable";		public static final String draggable = "draggable";		public static final String hidden = "hidden";		public static final String id = "id";		public static final String lang = "lang";		public static final String spellCheck = "spellcheck";		public static final String tabIndex = "tabindex";		public static final String title = "title";	}	private static Logger log = LoggerFactory.getLogger(Tag.class);	private String tagName;	private String tagAttr;	private String cssClass;	private String cssStyle;	private Set<String> classSet = new LinkedHashSet<String>();	private Map<String, Object> styleMap = new LinkedHashMap<String, Object>();	private Set<String> attrSet = new LinkedHashSet<String>();	private Map<String, Object> attrMap = new LinkedHashMap<String, Object>();	private Map<String, Object> dataMap = new LinkedHashMap<String, Object>();	public Tag() {		super(ContentType.tag);	}	public Tag(Integer type) {		super(type);	}	public Tag(String tagName) {		super(ContentType.tag);		this.tagName = tagName.trim().toLowerCase();	}	public Tag(String tagName, Integer type) {		super(type);		this.tagName = tagName.trim().toLowerCase();	}	public T accessKey(String altKey) {		if (EmptyUtil.not(altKey)) {			this.attrMap.put(Attr.accessKey, altKey);		} else {			log.error("accessKey: argument(altKey) is empty !");		}		return super.bean();	}	public T cssClass(String className) {		if (EmptyUtil.not(className)) {			this.classSet.add(className.trim());		} else {			log.error("cssClass: argument(className) is empty !");		}		return super.bean();	}	public T cssClass(String... classNames) {		if (EmptyUtil.not(classNames)) {			Arrays.asList(classNames).forEach(item -> this.classSet.add(item.trim()));		} else {			log.error("cssClass: argument(classNames) has empty !");		}				return super.bean();	}	public T contentEditable(boolean editable) {		this.attrMap.put(Attr.contentEditable, editable);		return super.bean();	}	public T draggable(boolean draggable) {		this.attrMap.put(Attr.draggable, draggable);		return super.bean();	}	public T hide(boolean hidden) {		if (hidden) {			this.attrSet.add(Attr.hidden);		} else {			this.attrSet.remove(Attr.hidden);		}		return super.bean();	}	public T id(String id) {		if (EmptyUtil.not(id)) {			this.attrMap.put(Attr.id, id.trim());		} else {			log.error("id: argument(id) is empty !");		}		return super.bean();	}	public T lang(String languageCode) {		if (EmptyUtil.not(languageCode)) {			this.attrMap.put(Attr.lang, languageCode.trim());		} else {			log.error("lang: argument(languageCode) is empty !");		}		return super.bean();	}	public T spellCheck(boolean check) {		this.attrMap.put(Attr.spellCheck, check);		return super.bean();	}	public T css(String key, Object value) {		if (EmptyUtil.not(key)) {			this.styleMap.put(this.attrName(key), this.attrValue(value));		} else {			log.error("css: argument(key) is empty !");		}		return super.bean();	}	public T css(Value value) {		if (value != null && EmptyUtil.not(value.getName()) ) {			this.styleMap.put(this.attrName(value.getName()), this.attrValue(value.getValue()));		} else {			log.error("css: argument(value) is empty !");		}		return super.bean();	}	public T css(Value... values) {		if (EmptyUtil.not((Object[]) values)) {			Arrays.asList(values).forEach(item -> this.css(item));		} else {			log.error("css: argument(values) is empty !");		}		return super.bean();	}	public T tabIndex(int index) {		if (index > 0) {			this.attrMap.put(Attr.tabIndex, index);		} else {			log.error("tabIndex: argument(index) must be positive !");		}		return super.bean();	}	public T title(String tip) {		if (EmptyUtil.not(tip)) {			this.attrMap.put(Attr.title, tip.trim());		} else {			log.error("title: argument(tip) is empty !");		}		return super.bean();	}	public T data(String key, Object value) {		if (EmptyUtil.not(key)) {			String dataName = key.trim();				String dataValue = this.attrValue(value);			if ("name".equals(dataName)) {				super.name(dataValue);			} else {				this.dataMap.put(dataName, dataValue);			}		} else {			log.error("data: argument(key) is empty !");		}		return super.bean();	}	public void build() {		List<String> items = new ArrayList<String>();		items.add("");			if (EmptyUtil.not(super.getName())) {			items.add(String.format("data-name=\"%s\"", super.getName()));		}		if (EmptyUtil.not(this.classSet)) {			this.cssClass = StringUtils.collectionToDelimitedString(this.classSet, " ");			items.add(String.format("class=\"%s\"", this.cssClass));		}		if (EmptyUtil.not(this.attrSet)) {			this.attrSet.forEach(attr -> items.add(String.format("%s", attr)));		}		if (EmptyUtil.not(this.attrMap)) {			this.attrMap.forEach((key, value) -> items.add(String.format("%s=\"%s\"", key, value)));		}		if (EmptyUtil.not(this.styleMap)) {			StringBuilder sb1 = new StringBuilder();			this.styleMap.forEach((key, value) -> sb1.append(String.format("%s:%s;", key, value)));			this.cssStyle = sb1.toString();			items.add(String.format("style=\"%s\"", this.cssStyle));		}		if (EmptyUtil.not(this.dataMap)) {			this.dataMap.forEach((key, value) -> items.add(String.format("data-%s=\"%s\"", key, value)));		}		this.tagAttr = StringUtils.collectionToDelimitedString(items, " ");	}	public boolean hasAttr(String name) {		if (EmptyUtil.not(name)) {			String key = this.attrName(name);			if (this.attrSet.contains(key) || this.attrMap.containsKey(key)) {				return true;			}		}		return false;	}	public Object getAttr(String name) {		if (EmptyUtil.not(name)) {			String key = this.attrName(name);			if (this.attrSet.contains(key)) {				return key;			}			if (this.attrMap.containsKey(key)) {				return this.attrMap.get(key);			}		}		return null;	}	public T removeAttr(String name) {		if (EmptyUtil.not(name)) {			String key = this.attrName(name);			if (this.attrSet.contains(key)) {				this.attrSet.remove(key);			} else if (this.attrMap.containsKey(key)){				this.attrMap.remove(key);			}		}		return super.bean();	}	public T removeAttr(String... names) {		if (EmptyUtil.not(names)) {			Arrays.asList(names).forEach(item -> this.removeAttr(item));		}		return super.bean();	}	public boolean hasClass(String name) {		if (EmptyUtil.not(name)) {			return this.classSet.contains(name.trim());		}		return false;	}	public T removeClass(String name) {		if (EmptyUtil.not(name)) {			this.classSet.remove(name.trim());		}		return super.bean();	}	public T removeClass(String... names) {		if (EmptyUtil.not(names)) {			Arrays.asList(names).forEach(item -> this.removeClass(item));		}		return super.bean();	}	public boolean hasStyle(String name) {		if (EmptyUtil.not(name)) {			return this.styleMap.containsKey(this.attrName(name));		}		return false;	}	public Object getStyle(String name) {		if (EmptyUtil.not(name)) {			return this.styleMap.get(this.attrName(name));		}		return null;	}	public T removeStyle(String name) {		if (EmptyUtil.not(name)) {			this.styleMap.remove(this.attrName(name));		}		return super.bean();	}	public T removeStyle(String... names) {		if (EmptyUtil.not(names)) {			Arrays.asList(names).forEach(item -> this.removeStyle(item));		}		return super.bean();	}	public boolean hasData(String name) {		if (EmptyUtil.not(name)) {			return this.dataMap.containsKey(name);		}		return false;	}	public Object getData(String name) {		if (EmptyUtil.not(name)) {			return this.dataMap.get(name);		}		return null;	}	public T removeData(String name) {		if (EmptyUtil.not(name)) {			if ("name".equals(name)) {				super.setName(null);			} else {				this.dataMap.remove(name);			}		}		return super.bean();	}	public T removeData(String... names) {		if (EmptyUtil.not(names)) {			Arrays.asList(names).forEach(item -> this.removeData(item));		}		return super.bean();	}	public T vue(String attribute) {		if (EmptyUtil.not(attribute)) {			this.attrSet.add("v-" + attribute);		} else {			log.error("vue: argument(attribute) has empty !");		}		return super.bean();			}	public T vue(String attribute, String variable) {		if (EmptyUtil.not(attribute, variable)) {			this.attrMap.put("v-" + attribute, variable);		} else {			log.error("vue: argument(attribute, variable) has empty !");		}		return super.bean();	}	public T vueBind(String attribute, String variable) {		if (EmptyUtil.not(attribute, variable)) {			this.attrMap.put(":" + attribute, variable);		} else {			log.error("vueBind: argument(attribute, variable) has empty !");		}		return super.bean();	}	public T vueOn(String event, String function) {		if (EmptyUtil.not(event, function)) {			this.attrMap.put("@" + event, function);		} else {			log.error("vueOn: argument(event, function) has empty !");		}		return super.bean();			}	public T vueClass(String express) {		if (EmptyUtil.not(express)) {			this.attrMap.put(":class", express);		} else {			log.error("vueClass: argument(express) has empty !");		}		return super.bean();	}	public T vueClass(String... classes) {		if (EmptyUtil.not(classes)) {			this.attrMap.put(":class", Arrays.asList(classes).toString());		} else {			log.error("vueClass: argument(classes) has empty !");		}		return super.bean();	}	public T vueStyle(String express) {		if (EmptyUtil.not(express)) {			this.attrMap.put(":style", express);		} else {			log.error("vueStyle: argument(express) has empty !");		}		return super.bean();	}	public T vueModel(String variable) {		if (EmptyUtil.not(variable)) {			this.attrMap.put("v-model", variable);		} else {			log.error("vueModel: argument(variable) has empty !");		}		return super.bean();	}	public T vueModel(String argument, String variable) {		if (EmptyUtil.not(argument, variable)) {			this.attrMap.put("v-model:" + argument, variable);		} else {			log.error("vueModel: argument(argument, variable) has empty !");		}		return super.bean();	}	@Override	public T copy() {		T bean = super.copy();		Tag<?> tag = (Tag<?>) bean;		tag.setClassSet(new LinkedHashSet<String>(this.classSet));		tag.setStyleMap(new LinkedHashMap<String, Object>(this.styleMap));		tag.setAttrSet(new LinkedHashSet<String>(this.attrSet));		tag.setAttrMap(new LinkedHashMap<String, Object>(this.attrMap));		tag.setDataMap(new LinkedHashMap<String, Object>(this.dataMap));		return bean;	}	protected String attrName(String name) {		if (EmptyUtil.not(name)) {			return name.trim().toLowerCase();		} else {			log.error("attrName: argument(key) is emtpy !");			return null;		}	}	protected String attrValue(Object value) {		if (EmptyUtil.not(value)) {			if (value instanceof String) {				return ((String) value).trim();			} else {				return value.toString();			}		} else {			return "";				}	}	protected boolean isAttr(String attrName) {		switch (this.attrName(attrName)) {		case Attr.accessKey:		case Attr.contentEditable:		case Attr.draggable:		case Attr.hidden:		case Attr.id:		case Attr.lang:		case Attr.spellCheck:		case Attr.tabIndex:		case Attr.title:			return true;		default:			log.error("Tag: attribute(\"" + attrName + "\") is invalid !");			return false;		}	}	public String getTagName() {		return tagName;	}	public void setTagName(String tagName) {		this.tagName = tagName;	}	public String getTagAttr() {		return tagAttr;	}	public void setTagAttr(String tagAttr) {		this.tagAttr = tagAttr;	}	public String getCssClass() {		return cssClass;	}	public void setCssClass(String cssClass) {		this.cssClass = cssClass;	}	public String getCssStyle() {		return cssStyle;	}	public void setCssStyle(String cssStyle) {		this.cssStyle = cssStyle;	}	public Set<String> getClassSet() {		return classSet;	}	public void setClassSet(Set<String> classSet) {		this.classSet = classSet;	}	public Map<String, Object> getStyleMap() {		return styleMap;	}	public void setStyleMap(Map<String, Object> styleMap) {		this.styleMap = styleMap;	}	public Set<String> getAttrSet() {		return attrSet;	}	public void setAttrSet(Set<String> attrSet) {		this.attrSet = attrSet;	}	public Map<String, Object> getAttrMap() {		return attrMap;	}	public void setAttrMap(Map<String, Object> attrMap) {		this.attrMap = attrMap;	}	public Map<String, Object> getDataMap() {		return dataMap;	}	public void setDataMap(Map<String, Object> dataMap) {		this.dataMap = dataMap;	}}